for img in image_paths:
    model(str(img), verbose=False)

end_time = time.time()
elapsed = end_time - start_time
fps = len(image_paths) / elapsed

print(f"Processed  : {len(image_paths)} images")
print(f"Total time : {elapsed:.2f} seconds")
